<script setup lang="ts">
import {ref,nextTick,toRaw,onUnmounted,computed} from 'vue';
import {X,Plus,ExternalLink} from 'lucide-vue-next';
import {agendaView,tasksBusy,taskSnapshot,changeTasks} from '../composables/tasks';
import {learningTasks,saveLearningPlan,openLearningItem} from '../composables/learning';
import {learningTaskState} from '../domain/learning-status';
import {beijingDay,shiftDay,validateTask,type CampusTask} from '../domain/agenda';
import {createTask,plannedDay,replanTask} from '../domain/tasks';
import {taskStore} from '../services/task-store';
import {uid} from '../domain/schedule';
const emit=defineEmits<{saved:[message:string]}>();
const draft=ref<CampusTask|null>(null),baseline=ref(''),error=ref(''),discard=ref(false),removeIntent=ref(false),newStep=ref(''),titleInput=ref<HTMLInputElement>(),saving=ref(false);
let existing=false,previousFocus:HTMLElement|null=null;
const original=computed(()=>draft.value?.source==='chaoxing'?learningTasks.value.find(t=>t.id===draft.value?.id):undefined);
const state=computed(()=>original.value?learningTaskState(original.value):null);
const day=computed({get:()=>draft.value?plannedDay(draft.value)||'':'',set:(v:string)=>{if(!draft.value)return;if(draft.value.plannedAt&&v)draft.value.plannedAt=v+draft.value.plannedAt.slice(10);else{draft.value.plannedAt=null;draft.value.plannedDay=v||null}}});
function edit(task?:CampusTask,defaultDay?:string){existing=!!task;previousFocus=document.activeElement as HTMLElement;draft.value=JSON.parse(JSON.stringify(task||{...createTask('新任务',uid()),title:''}));if(defaultDay&&!task)draft.value!.plannedDay=defaultDay;baseline.value=JSON.stringify(draft.value);error.value='';newStep.value='';discard.value=false;removeIntent.value=false;agendaView.editor=true;if(!task)void nextTick(()=>titleInput.value?.focus());else void nextTick(()=>document.querySelector<HTMLButtonElement>('.task-sheet header button')?.focus())}
function close(){agendaView.editor=false;draft.value=null;void nextTick(()=>previousFocus?.isConnected&&previousFocus.focus())}
function requestBack(){if(!draft.value)return false;if(saving.value)return true;if(removeIntent.value){removeIntent.value=false;return true}if(discard.value){discard.value=false;return true}if(newStep.value.trim()||JSON.stringify(draft.value)!==baseline.value){discard.value=true;return true}close();return true}
function trapFocus(e:KeyboardEvent){const el=e.currentTarget as HTMLElement;const a=[...el.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),summary')].filter(x=>x.getClientRects().length);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus()}}
function addStep(){if(!draft.value||!newStep.value.trim())return;draft.value.steps!.push({id:uid(),title:newStep.value.trim(),completed:false});newStep.value=''}
function setDay(offset:number){if(draft.value)draft.value=replanTask({...draft.value},shiftDay(beijingDay(),offset))}
function setTimed(e:Event){if(!draft.value)return;if((e.target as HTMLInputElement).checked){draft.value.plannedAt=(day.value||beijingDay())+'T09:00';draft.value.plannedDay=null}else{draft.value.plannedDay=day.value||null;draft.value.plannedAt=null}}
function repeatChanged(e:Event){if(!draft.value)return;const kind=(e.target as HTMLSelectElement).value;draft.value.repeat=kind==='none'?null:{kind:kind as NonNullable<CampusTask['repeat']>['kind'],interval:1,weekdays:[1]}}
function toggleWeekday(d:number){const r=draft.value?.repeat;if(r)r.weekdays=r.weekdays.includes(d)?r.weekdays.filter(x=>x!==d):[...r.weekdays,d]}
function addReminder(){draft.value?.reminders!.push({id:uid(),anchor:draft.value.deadline?'deadline':'start',minutes:30})}
async function save(){if(!draft.value||saving.value)return;try{saving.value=true;error.value='';addStep();if(draft.value.source==='chaoxing'){await saveLearningPlan({...toRaw(draft.value),plannedAt:draft.value.plannedAt||null});emit('saved','个人安排已保存，提交状态以学习通为准')}else{const task=validateTask({...toRaw(draft.value),plannedAt:draft.value.plannedAt||null,plannedDay:draft.value.plannedDay||null,deadline:draft.value.deadline||null,updatedAt:new Date().toISOString()});await changeTasks(()=>taskStore.upsert(task,existing?JSON.parse(baseline.value).updatedAt:undefined));emit('saved','待办已保存到本机')}close()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function remove(){if(!draft.value)return;try{await changeTasks(()=>taskStore.remove(draft.value!.id));emit('saved','任务已删除');close()}catch(e){error.value=(e as Error).message}}
async function openOriginal(){if(!draft.value)return;try{await openLearningItem(draft.value)}catch(e){error.value=(e as Error).message}}
defineExpose({edit,requestBack});onUnmounted(()=>agendaView.editor=false);
</script>
<template>
<Teleport to="body"><div v-if="draft" class="task-sheet-backdrop" @click.self="requestBack"><form class="task-sheet daily-detail" role="dialog" aria-modal="true" aria-label="任务详情" @keydown.tab="trapFocus" @keydown.esc.stop.prevent="requestBack" @submit.prevent="save">
<header><button type="button" class="icon-button" aria-label="关闭任务详情" @click="requestBack"><X :size="20"/></button><strong>{{draft.source==='chaoxing'?'作业详情':'任务详情'}}</strong><button class="primary" :disabled="tasksBusy||saving">{{draft.source==='chaoxing'?'保存安排':'保存待办'}}</button></header>
<p v-if="error" role="alert" class="task-message danger">{{error}}</p>
<div v-if="discard" class="task-confirm" role="alert"><strong>修改尚未保存</strong><button type="button" @click="discard=false">继续编辑</button><button type="button" @click="close">放弃修改</button></div>
<template v-if="draft.source==='chaoxing'"><h2 class="detail-title">{{draft.title}}</h2><p class="detail-meta">{{draft.course}}</p><span class="learning-state" :class="state?.key">{{state?.label}}</span><p class="detail-deadline">{{draft.deadline?'截止 '+draft.deadline.replace('T',' '):'截止时间待核对'}}</p><p v-if="original?.platformStale" class="task-hint">上次同步记录，提交状态待更新</p><button type="button" class="primary original-action" @click="openOriginal">去学习通 <ExternalLink :size="15"/></button></template>
<label v-else class="task-title-field"><span>准备做什么？</span><input ref="titleInput" v-model="draft.title" aria-label="待办标题" maxlength="100" required placeholder="输入任务标题"/></label>
<section class="detail-plan"><h3>什么时候做</h3><div class="day-shortcuts"><button type="button" :aria-pressed="day===beijingDay()" @click="setDay(0)">今天</button><button type="button" :aria-pressed="day===shiftDay(beijingDay(),1)" @click="setDay(1)">明天</button><button type="button" :aria-pressed="!day" @click="day=''">未安排</button></div><label>计划日期<input v-model="day" type="date" aria-label="计划日期"/></label><details class="detail-options" :open="!!draft.plannedAt"><summary>具体时间与时长 <span>{{draft.plannedAt?.slice(11)||'可选'}}</span></summary><label class="task-pin"><input type="checkbox" :checked="!!draft.plannedAt" @change="setTimed"/>指定开始时间</label><div v-if="draft.plannedAt" class="task-detail-grid"><label>计划开始<input v-model="draft.plannedAt" type="datetime-local" aria-label="任务计划开始"/></label><label>预计分钟<input v-model.number="draft.durationMinutes" type="number" min="5" max="1440" aria-label="任务预计时长"/></label></div></details></section>
<label v-if="draft.source==='chaoxing'" class="prepared-check"><input v-model="draft.prepared" type="checkbox"/>已做完，等待提交<small>仍会保留平台提交提醒</small></label>
<details v-if="draft.source==='chaoxing'" class="detail-options"><summary>作业要求与原始信息</summary><p class="detail-description">{{draft.platformDescription||'暂未读取到作业要求，请前往学习通查看。'}}</p><small>{{draft.platformStatusText}} · {{draft.timeText}}</small></details>
<details class="detail-options"><summary>截止、提醒与重复 <span>{{draft.reminders?.length?draft.reminders.length+' 条提醒':'可选'}}</span></summary><label>截止时间<input v-model="draft.deadline" :disabled="draft.source==='chaoxing'" type="datetime-local" aria-label="待办截止时间"/></label><p v-if="draft.source==='chaoxing'" class="task-hint">截止时间由学习通提供，个人安排不会修改它。</p><p v-if="day&&draft.deadline&&day>draft.deadline.slice(0,10)" class="task-hint danger">计划日期晚于截止日期，请留意提交要求。</p>
<label v-if="draft.source!=='chaoxing'">重复<select :value="draft.repeat?.kind||'none'" aria-label="任务重复规则" @change="repeatChanged"><option value="none">不重复</option><option value="daily">每天</option><option value="weekdays">周一至周五</option><option value="weekly">每周</option><option value="days">指定星期</option><option value="interval">自定义天数</option></select></label><label v-if="draft.repeat?.kind==='interval'">间隔天数<input v-model.number="draft.repeat.interval" type="number" min="1" max="365"/></label><div v-if="draft.repeat?.kind==='days'" class="day-shortcuts"><button v-for="(d,i) in ['一','二','三','四','五','六','日']" :key="d" type="button" :aria-pressed="draft.repeat.weekdays.includes(i+1)" @click="toggleWeekday(i+1)">{{d}}</button></div>
<div class="task-reminders"><h3>提醒 <button type="button" :disabled="(draft.reminders?.length??0)>=5" @click="addReminder">添加提醒</button></h3><div v-for="(r,i) in draft.reminders" :key="r.id"><select v-model="r.anchor" :aria-label="'提醒依据 '+(i+1)"><option value="start">开始前</option><option value="deadline">截止前</option><option value="absolute">指定时间</option></select><input v-if="r.anchor==='absolute'" v-model="r.at" type="datetime-local" :aria-label="'提醒时间 '+(i+1)"/><input v-else v-model.number="r.minutes" type="number" min="0" max="525600" :aria-label="'提前分钟 '+(i+1)"/><button type="button" :aria-label="'删除提醒 '+(i+1)" @click="draft.reminders!.splice(i,1)"><X :size="14"/></button></div><p class="task-hint">提前量以分钟计。仅安排日期不会触发开始提醒；系统提醒在「我的」开启。</p></div></details>
<details class="detail-options"><summary>步骤与备注 <span>{{draft.steps?.length?draft.steps.length+' 个步骤':'可选'}}</span></summary><section class="task-steps"><div v-for="(step,i) in draft.steps" :key="step.id"><input v-model="step.completed" type="checkbox" :aria-label="'完成步骤 '+step.title"/><input v-model="step.title" :aria-label="'步骤标题 '+(i+1)" maxlength="100"/><button type="button" :aria-label="'删除步骤 '+(i+1)" @click="draft.steps!.splice(i,1)"><X :size="14"/></button></div><div><input v-model="newStep" aria-label="新步骤标题" maxlength="100" placeholder="添加一个步骤" @keydown.enter.prevent="addStep"/><button type="button" :disabled="(draft.steps?.length??0)>=50" @click="addStep"><Plus :size="18"/></button></div></section><label>备注<textarea v-model="draft.notes" aria-label="待办备注" maxlength="1000" rows="3"/></label></details>
<details class="detail-options"><summary>分类与优先级</summary><label v-if="draft.source!=='chaoxing'">关联课程<input v-model="draft.course" aria-label="关联课程" maxlength="100" placeholder="可不填"/></label><label>优先级<select v-model.number="draft.priority" aria-label="任务优先级"><option :value="0">普通</option><option :value="1">低</option><option :value="2">中</option><option :value="3">高</option></select></label><label class="task-pin"><input v-model="draft.pinned" type="checkbox"/>置顶任务</label></details>
<button v-if="draft.source!=='chaoxing'&&taskSnapshot.tasks.some(t=>t.id===draft!.id)" type="button" class="text-button danger" @click="removeIntent=true">删除任务</button><div v-if="removeIntent" class="task-confirm"><span>删除这项任务？</span><button type="button" @click="removeIntent=false">取消</button><button type="button" class="danger" @click="remove">确认删除</button></div>
</form></div></Teleport>
</template>
